struct stringx {
    char data[16];
    stringx(const stringx&);
    stringx(const char*, int = -1);
    ~stringx();
};

extern stringx ksGlobalTextArray[];

class HelpbarFE {
public:
    void Reset();
    void ChangeBtn(int, bool, stringx);
    void Reformat();
    void AddArrowH(stringx text = stringx("")) {
        ChangeBtn(0, true, text);
        ChangeBtn(2, false, "");
    }
    void RemoveX() {
        ChangeBtn(3, false, "");
    }
};

class FEManager {
    char pad[0x156A4];
public:
    HelpbarFE* helpbar;
};

class FEGraphicalMenu {
    char pad[0x13C];
public:
    FEManager* manager;
    void OnActivate();
};

class FEMultiMenu : public FEGraphicalMenu {
    char pad[0x2A8];
};

class LogbookFrontEnd : public FEMultiMenu {
    int cur_spread;
    int max_spread;
public:
    void ReadNotesFromFile();
    void UpdateUnlockedNotes(int = 0);
    void OnActivate();
};

enum { GT_FE_MENU_SWITCH = 0 };

void LogbookFrontEnd::OnActivate()
{
	ReadNotesFromFile();
	FEMultiMenu::OnActivate();
	cur_spread = 0;
	UpdateUnlockedNotes();

	manager->helpbar->Reset();
	manager->helpbar->AddArrowH(ksGlobalTextArray[GT_FE_MENU_SWITCH]);
	manager->helpbar->RemoveX();
	manager->helpbar->Reformat();
}
